SELECT * FROM (SELECT CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END AS rating_bucket, city, ROUND(AVG(rating), 2) AS avg_rating, COUNT(CASE WHEN city = 'Berlin' THEN 1 END) AS berlin_count FROM suppliers WHERE rating <= 4.1 GROUP BY CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END, city) AS x WHERE berlin_count < 6 ORDER BY berlin_count, avg_rating DESC
